.stats {
  display: flex;
  flex-wrap: wrap;
  gap: 12px 24px;
  margin: 0 0 16px;
}
.stats div {
  min-width: 8ch;
}
dt,
dd {
  display: inline;
}
dt {
  color: var(--secondary);
  font-size: 14px;
}
dd {
  margin: 0;
  font-variant-numeric: tabular-nums;
}
.victory {
  padding: 12px 16px;
  margin-bottom: 12px;
  color: var(--text);
  border: 1px solid var(--border);
  border-radius: 8px;
}
.celebrate {
  animation: victory-pulse 600ms ease-out 1;
}
@keyframes victory-pulse {
  50% {
    background: var(--panel);
    opacity: 0.75;
  }
}
.card {
  position: relative;
  width: 100%;
  aspect-ratio: 1;
  padding: 0;
  scroll-margin: 6px;
  border: 2px solid var(--border);
  border-radius: 8px;
  background: var(--back);
  color: var(--text);
  touch-action: manipulation;
  user-select: none;
  -webkit-user-select: none;
  transition: border-color 120ms ease;
  display: grid;
  place-items: center;
  cursor: pointer;
}
.card:hover {
  border-color: var(--text);
}
.card.revealed,
.card.matched {
  background: var(--face);
}
.card.matched {
  border-color: var(--green);
}
.card > svg {
  display: block;
  width: 100%;
  height: 100%;
}
.card-back {
  width: 12px;
  height: 12px;
  border: 2px solid var(--secondary);
  transform: rotate(45deg);
}
/* A corner mark wider than about 17% of the card would reach the top-right marker. */
.card > .matched-mark {
  position: absolute;
  right: 0;
  top: 0;
  width: 16%;
  height: 16%;
  color: var(--green);
}

